window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[230]={"id":"230","numero":230,"titre":"Douleur thoracique aiguë","objectifs":[{"id":"230-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une douleur thoracique aiguë","contenu":"<div class=\"notion-course\"><p>La <span>douleur <span class=\"nc-blue_bg\">thoracique</span> aiguë</span> est une douleur ressentie dans la région du thorax, d'installation récente. C'est un <strong>motif de recours très fréquent aux urgences</strong> : l'enjeu n'est pas de poser d'emblée un diagnostic précis, mais d'<strong>éliminer en priorité une <span>urgence</span> vitale</strong>.</p>\n      <p>Les structures thoraciques susceptibles d'être <strong>douloureuses</strong> sont :</p>\n      <ul>\n        <li>la <span>paroi</span> — côtes, muscles, articulations chondro-costales ;</li>\n        <li>les <span>enveloppes séreuses</span> — plèvre, péricarde ;</li>\n        <li>le <span>cœur</span> ;</li>\n        <li>l'<span>œsophage</span> et l'<span>aorte</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le <strong>parenchyme pulmonaire ne fait pas mal</strong> — il n'est pas innervé pour la douleur. Seules les pathologies pulmonaires survenant <strong>au contact de la plèvre</strong> sont éventuellement sources de <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span>.\n      </div>\n      <p>Les causes fréquentes comprennent les douleurs pariétales, œsophagiennes et anxieuses, ainsi que les syndromes coronariens. Leur fréquence dépend du lieu de consultation ; elle ne doit pas dicter seule le tri des urgences.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":0},{"id":"230-2","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir rechercher une détresse vitale devant une douleur thoracique","contenu":"<div class=\"notion-course\"><p>Devant toute <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span>, la <strong>première étape</strong> — avant même de chercher la cause — est de <strong>rechercher une <span>détresse vitale</span></strong> par un examen rapide et systématisé. Trois territoires sont explorés.</p>\n      <table>\n        <thead><tr><th><span>Détresse</span></th><th>Signes à rechercher</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Détresse respiratoire</span></td>\n            <td>\n              <strong>Fréquence :</strong> <span>polypnée</span> <span>&gt; 30/min</span> ou <span>bradypnée</span> <span>&lt; 10/min</span> (voire pause respiratoire)<br>\n              <strong>Lutte :</strong> <span>tirage</span> par mise en jeu des muscles respiratoires accessoires<br>\n              <strong>Retentissement :</strong> <span>sueurs</span> ; <span>cyanose</span> ; <span>désaturation</span> (<span>SpO₂ &lt; 90 %</span>) ; encéphalopathie respiratoire\n            </td>\n          </tr>\n          <tr>\n            <td><span>Détresse hémodynamique</span></td>\n            <td><b>Arrêt circulatoire :</b> patient inconscient qui ne respire pas normalement (gasps possibles). Pour un soignant, recherche d’un pouls central pendant au plus 10 secondes ; en cas de doute, commencer la réanimation. <br><b>Choc :</b> hypoperfusion, pâleur, marbrures, oligurie ; hypotension fréquente mais non obligatoire. <br>Autres signes : turgescence jugulaire, signes de cœur pulmonaire aigu ; <b>pouls paradoxal</b> = baisse inspiratoire de la pression artérielle systolique supérieure à 10 mmHg.</td>\n          </tr>\n          <tr>\n            <td><span>Atteinte neurologique</span></td>\n            <td>Troubles de la conscience : <span>confusion</span> ; <span>agitation</span> ; <span>convulsions</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span>Urgence</span>.</strong> La présence d'<strong>un seul</strong> de ces signes impose une prise en charge immédiate en <strong>SAUV / <span>réanimation</span></strong>, sans attendre les résultats paracliniques.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span>choc</span></em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li><li><a href=\"https://www.erc.edu/science-research/guidelines/guidelines-2025/guidelines-2025-english/\" target=\"_blank\" rel=\"noopener noreferrer\">ERC · Réanimation, recommandations 2025</a></li></ul><p></p></details>","frequence":0},{"id":"230-3","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","contenu":"<div class=\"notion-course\"><p>Les <span>signes de gravité</span> d'une <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span> sont les signes de <strong><span>détresse vitale</span></strong> (respiratoire, hémodynamique, neurologique). Leur présence <strong>court-circuite la démarche diagnostique</strong> : on ne peut plus attendre les examens, des <strong>décisions thérapeutiques immédiates</strong> s'imposent.</p>\n      <p><strong>Mise en condition immédiate</strong>, menée en parallèle de l'évaluation :</p>\n      <ul>\n        <li><span>scope</span> <span>ECG</span> continu + monitorage de la <span>pression artérielle</span> et de la <span>SpO₂</span> ;</li>\n        <li>pose d'une <strong>voie veineuse périphérique</strong> ;</li>\n        <li><span>oxygénothérapie</span> en cas de désaturation ;</li>\n        <li>prise en charge en <strong>SAUV</strong>, à proximité immédiate d'un chariot d'<span>urgence</span> et d'un <span>défibrillateur</span>.</li>\n      </ul>\n      <p>Certains <span>signes de gravité</span> orientent vers une <strong>décision thérapeutique spécifique et urgente</strong> :</p>\n      <table>\n        <thead><tr><th><span>Signe de gravité</span></th><th>Décision immédiate</th></tr></thead>\n        <tbody>\n          <tr><td><span>Arrêt circulatoire</span> (pouls non perçu, inconscience)</td><td>Réanimation cardio-pulmonaire immédiate, alerte et défibrillateur ; choc si rythme choquable.</td></tr>\n          <tr><td><span>Pouls paradoxal</span> + <span>turgescence jugulaire</span> + <span>hypotension</span> (<span>tamponnade</span>)</td><td><span>Drainage péricardique</span> en <span>urgence</span></td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Asymétrie tensionnelle</span></span>, <span class=\"nc-yellow_bg\">abolition d'un pouls</span>, <span>choc</span> (<span><span>dissection</span> aortique</span> de type A)</td><td>Avis aortique/chirurgical immédiat si type A suspecté. Ne pas débuter empiriquement anticoagulants ou fibrinolyse devant une suspicion de dissection ; toute indication associée exige une décision spécialisée.</td></tr>\n          <tr><td><span>État de choc</span> / <span>hypotension</span> persistante</td><td>Orientation en <span>réanimation</span> ; traitement étiologique sans délai</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Principe.</strong> Devant une <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span> grave, la priorité est de <strong>traiter la <span>menace</span> vitale</strong> et d'orienter vers le plateau technique adapté — le bilan étiologique complet vient ensuite.\n      </div><div class=\"callout\"><p>Le pneumothorax compressif et la <span class=\"nc-red nc-bold\">rupture</span> œsophagienne sont aussi des urgences vitales. Le bilan ciblé et les soins sont menés en parallèle.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li><li><a href=\"https://www.erc.edu/science-research/guidelines/guidelines-2025/guidelines-2025-english/\" target=\"_blank\" rel=\"noopener noreferrer\">ERC · Réanimation, recommandations 2025</a></li></ul><p></p></details>","frequence":0},{"id":"230-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","contenu":"<div class=\"notion-course\"><p>Devant une <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span>, après avoir écarté la <span>détresse vitale</span>, la <strong>2ᵉ étape</strong> consiste à évoquer systématiquement les <strong>4 urgences cardio-vasculaires</strong>, regroupées sous le moyen mnémotechnique <span>PIED</span> :</p>\n      <ul>\n        <li><strong>P</strong> — <span>Péricardite</span> ;</li>\n        <li><strong>I</strong> — <span>Infarctus</span> (<span>syndrome coronarien aigu</span>) ;</li>\n        <li><strong>E</strong> — <span>Embolie pulmonaire</span> ;</li>\n        <li><strong>D</strong> — <span>Dissection aortique</span>.</li>\n      </ul>\n      <p>La sémiologie oriente vers une cause coronaire ou une autre cause, sans permettre à elle seule d’exclure un SCA.</p>\n      <table>\n        <thead><tr><th>Critère</th><th>Douleur <span>ischémique</span></th><th>Douleur non <span>ischémique</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Caractéristiques</strong></td><td><span>Constriction</span>, <span>pesanteur</span>, brûlure</td><td>Acérée, en <span class=\"nc-red nc-bold\">coup de poignard</span>, augmentée par la respiration</td></tr>\n          <tr><td><strong>Siège</strong></td><td>Rétrosternal ; médiothoracique ; irradiant cou, épaules, avant-bras, mâchoire ; associé à <span>sueurs</span> et <span>nausées</span></td><td>Sous-mammaire gauche ; hémithorax gauche ; punctiforme (montré du doigt) ; dorsal (<span>dissection</span>)</td></tr>\n          <tr><td><strong>Facteurs déclenchants</strong></td><td>Effort ; stress ; énervement ; temps froid</td><td>Après la fin de l'effort ; soulagement par l'effort ; provoquée par un mouvement particulier du corps</td></tr>\n          <tr><td><strong>Durée</strong></td><td>Minutes</td><td>Secondes, ou heures (en l'absence d'élévation des <span>troponines</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Chaque <span>urgence</span> a un <strong>profil clinique évocateur</strong> qu'il faut savoir reconnaître :</p>\n      <table>\n        <thead><tr><th>Critère</th><th><span>SCA</span> (<span>infarctus</span>)</th><th><span><span>Dissection</span> aortique</span></th><th><span>Embolie pulmonaire</span></th><th>Péricardite</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Terrain</span></strong></td><td><span>FDR cardio-vasculaires</span></td><td>FDRCV, notamment <span>HTA</span></td><td>Âge, <span>comorbidités</span>, <span>chirurgie</span> récente, néoplasie</td><td>Sujet jeune, contage <span>viral</span></td></tr>\n          <tr><td><strong>Mode de survenue</strong></td><td>Brutal</td><td>Brutal</td><td>Brutal ou progressif, souvent associé à une dyspnée</td><td>Aigu</td></tr>\n          <tr><td><strong>Horaire</strong></td><td>Effort, repos</td><td>Repos</td><td>Repos</td><td>Inspiration, décubitus</td></tr>\n          <tr><td><strong>Localisation, <span>irradiation</span></strong></td><td>Rétrosternale, épigastrique, mâchoire, bras, interscapulaire</td><td>Rétrosternale, <span>transfixiante</span></td><td>Latéro- ou basithoracique</td><td>Rétrosternale</td></tr>\n          <tr><td><strong>Type</strong></td><td><span>Constrictive</span>, brûlure</td><td><span><span class=\"nc-red nc-bold\">Coup de poignard</span></span></td><td>—</td><td><span>Constrictive</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Plaintes cardinales.</strong> Quelle que soit l'<span>urgence</span> évoquée, 4 plaintes sont systématiquement renseignées : <strong><span>douleur <span class=\"nc-blue_bg\">thoracique</span></span>, <span>dyspnée</span>, <span>syncope</span>, <span>palpitations</span></strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span>Syndrome coronarien</span> aiguë · 235 — Péricardite aiguë · 226 — <span>Thrombose veineuse profonde</span> - EP</em></p><div class=\"callout\"><p>PIED est un aide-mémoire cardiovasculaire, pas une liste exhaustive. Une douleur pleurale, reproductible, très brève ou anxieuse n’exclut pas à elle seule une urgence. La dissection peut elle-même provoquer des ischémies d’organes.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":1},{"id":"230-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","contenu":"<div class=\"notion-course\"><p>La <span>dissection aortique</span> est une <span>urgence</span> rare mais gravissime : une <strong><span><span class=\"nc-red nc-bold\">rupture</span></span> de l'intima</strong> crée une porte d'entrée, le sang s'engouffre dans un <span><span class=\"nc-brown_bg\">faux chenal</span></span> qui clive la média. Le <span class=\"nc-brown_bg\">faux chenal</span> peut s'étendre (sens antérograde ou rétrograde), atteindre les collatérales de l'aorte, et surtout exposer à la <span><span class=\"nc-red nc-bold\">rupture</span> aortique</span> mortelle.</p>\n      <p><strong><span>Terrain</span> et facteurs favorisants :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">HTA ancienne</span></span> et <span><span class=\"nc-orange_bg\">athérome</span></span> — sujet âgé, en général <span><span class=\"nc-pink nc-bold\">&gt; 60 ans</span></span> ;</li>\n        <li><span><span class=\"nc-orange_bg\">syndrome de Marfan</span></span> ou d'<span>Ehlers-Danlos</span> — sujet plus jeune ;</li>\n        <li>antécédent familial de maladie aortique ;</li>\n        <li><span class=\"nc-orange_bg\">anévrisme de l'aorte thoracique</span>, valvulopathie aortique connue ;</li>\n        <li>antécédent de <span>chirurgie</span> aortique.</li>\n      </ul>\n      <p><strong>Signes fonctionnels — la douleur :</strong> début <span class=\"nc-blue_bg\">thoracique</span> <strong>aigu et brutal</strong>, <strong>intense</strong>, à type de <span><span class=\"nc-red nc-bold\">déchirement</span></span>, en <span><span class=\"nc-red nc-bold\">coup de poignard</span></span> (<strong>transfixiante</strong>) — irradiant dans le <strong><span class=\"nc-blue_bg\">dos</span></strong>, <span>migratrice</span>, descendant vers les <span class=\"nc-blue_bg\">lombes</span> et les <span class=\"nc-blue_bg\">membres inférieurs</span>, parfois accompagnée d'une <span>syncope</span>.</p>\n      <p><strong>Signes physiques :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-yellow_bg\">asymétrie tensionnelle</span></span> (différence <span>&gt; 20 mmHg</span>), <span><span class=\"nc-yellow_bg\">abolition d'un pouls</span></span> ;</li>\n        <li><span><span class=\"nc-yellow_bg\">souffle d'insuffisance aortique</span></span> (dans <span>50 %</span> des dissections de type A) ;</li>\n        <li><span class=\"nc-orange_bg\">poussée d'</span><span><span class=\"nc-orange_bg\">HTA</span></span>, ou au contraire <span>hypotension / choc</span>.</li>\n      </ul>\n      <p><strong>Complications parfois révélatrices</strong> (par extension du <span class=\"nc-brown_bg\">faux chenal</span> aux collatérales) :</p>\n      <ul>\n        <li><span><span class=\"nc-red_bg\">déficit neurologique</span></span> (<span>AVC</span>), <span><span class=\"nc-red_bg\">infarctus</span></span><span class=\"nc-red_bg\"> médullaire</span> (syndrome médullaire aigu) ;</li>\n        <li><span><span class=\"nc-red_bg\">hémopéricarde avec tamponnade</span></span> ;</li>\n        <li><span><span class=\"nc-red_bg\">infarctus</span></span><span class=\"nc-red_bg\"> mésentérique</span>, <span><span class=\"nc-red_bg\">ischémie aiguë</span></span><span class=\"nc-red_bg\"> d'un membre</span>, <span><span class=\"nc-red_bg\">insuffisance rénale aiguë</span></span>.</li>\n      </ul>\n      <table>\n        <thead><tr><th><span>Score</span> de probabilité clinique de <span>dissection</span></th><th>Cotation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Terrain</span> évocateur :</strong> <span><span class=\"nc-orange_bg\">syndrome de Marfan</span></span> ; <span class=\"nc-brown_bg\">ATCD familial de maladie aortique</span> ; anévrisme ou valvulopathie aortique connus ; <span class=\"nc-pink_bg\">ATCD de </span><span><span class=\"nc-pink_bg\">chirurgie</span></span><span class=\"nc-pink_bg\"> aortique</span></td><td><span>1 point</span></td></tr>\n          <tr><td><strong>Douleur évocatrice :</strong> <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span>, dorsale ou abdominale, de début brutal, intense, à type de <span class=\"nc-red nc-bold\">déchirement</span></td><td><span>1 point</span></td></tr>\n          <tr><td><strong>Signes à l'examen :</strong> <span class=\"nc-yellow_bg\">abolition d'un pouls</span> ; <span><span class=\"nc-yellow_bg\">asymétrie</span></span><span class=\"nc-yellow_bg\"> tensionnelle</span> ; <span class=\"nc-red_bg\">déficit neurologique</span> focal ; insuffisance aortique ; <span><span class=\"nc-orange_bg\">hypotension</span></span><span class=\"nc-orange_bg\"> ou </span><span><span class=\"nc-orange_bg\">choc</span></span></td><td><span>1 point</span></td></tr>\n        </tbody>\n      </table>\n      <p>ADD-RS : un point par catégorie de risque, soit 0 à 3. Un score 0 correspond à un risque faible, 1 à un risque intermédiaire, 2–3 à un risque élevé. Certains parcours du collège regroupent 0–1 pour une stratégie d’exclusion combinée ; le score seul ne suffit jamais.</p>\n      <div><b>Piège majeur.</b> Une dissection peut mimer un <span class=\"nc-red nc-bold\">SCA</span> ou une embolie pulmonaire. Devant une suspicion significative, ne pas commencer empiriquement anticoagulant curatif ou fibrinolyse avant évaluation urgente. Les indications antithrombotiques concomitantes relèvent de l’équipe spécialisée.</div>\n      <div class=\"callout callout-info\">\n        <strong><span>Classification</span> de Stanford</strong> (référence) — <strong>type A</strong> : la <span>dissection</span> intéresse l'<span class=\"nc-yellow_bg\">aorte ascendante</span> → <strong><span>chirurgie</span> en <span>urgence</span></strong> (risque de <span><span class=\"nc-red nc-bold\">rupture</span></span>, tamponnade, insuffisance aortique massive). <strong>Type B</strong> : la dissection n'intéresse pas l'<span class=\"nc-yellow_bg\">aorte ascendante</span> → pas de chirurgie urgente en l'absence de complication, <strong>contrôle de la pression artérielle</strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span>HTA</span> · 233 — Valvulopathie</em></p><ul><li>L’absence de douleur typique, d’asymétrie des pouls ou de souffle n’exclut pas la dissection. Rechercher aussi bicuspidie, maladie aortique familiale et grossesse/post-partum sur aortopathie.</li><li>Stanford B compliquée (<span class=\"nc-red nc-bold\">rupture</span>, malperfusion, douleur ou HTA réfractaire) : avis aortique urgent, intervention souvent endovasculaire. La forme non compliquée relève initialement du traitement médical et d’une surveillance spécialisée.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":1},{"id":"230-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","contenu":"<div class=\"notion-course\"><h4>Une démarche simultanée et orientée</h4><ol><li>Rechercher et traiter les défaillances vitales ; constantes, SpO₂, monitorage et voies d’abord si nécessaire.</li><li>Évoquer SCA, dissection, EP et péricardite/tamponnade, ainsi que pneumothorax compressif et <span class=\"nc-red nc-bold\">rupture</span> œsophagienne.</li><li>ECG <b>12 dérivations en moins de 10 minutes</b> si suspicion de SCA ; compléter par les dérivations droites/postérieures selon le contexte et répéter si nécessaire.</li><li>Troponine ultrasensible pour suspicion de SCA sans retarder une reperfusion. Radiographie, échographie et biologie choisies selon la question ; les <span class=\"nc-blue_bg\">D-dimères</span> dépendent de la probabilité clinique.</li></ol><h4>Suspicion de syndrome aortique aigu</h4><table><thead><tr><th>Situation</th><th>Démarche</th></tr></thead><tbody><tr><td>Patient stable, suspicion élevée</td><td><span class=\"nc-blue_bg\">Angio-TDM</span> aortique sans délai : porte d’entrée, extension, branches et complications. Ne pas attendre des <span class=\"nc-blue_bg\">D-dimères</span>.</td></tr><tr><td>Patient stable, faible probabilité retenue</td><td>Une stratégie validée combinant probabilité clinique et <span class=\"nc-blue_bg\">D-dimères</span> peut aider à exclure le diagnostic. Des <span class=\"nc-blue_bg\">D-dimères</span> négatifs isolés ou une radiographie normale ne suffisent pas si la suspicion demeure.</td></tr><tr><td>Instabilité</td><td>Avis aortique immédiat ; ETT au lit pour complications et ETO si disponible/appropriée. <span class=\"nc-blue_bg\">Angio-TDM</span> si le transport est possible sans compromettre les soins ; ne pas imposer un transfert dangereux vers le scanner.</td></tr></tbody></table><p>Le flap intimal séparant vrai et <span class=\"nc-brown_bg\">faux chenal</span> signe la dissection. Une ETT négative ne l’exclut pas. L’<span class=\"nc-blue_bg\">angio-TDM</span> cartographie l’ensemble de l’aorte et ses branches ; l’ETO est particulièrement utile en contexte instable ou périopératoire.</p><figure class=\"obj-figure\">\n        <img src=\"../assets/images/230/tdm-dissection-aortique-stanford-a.png\" alt=\"Angio-TDM thoracique en coupe axiale — dissection aortique de type A : double chenal de l&#x27;aorte ascendante\" loading=\"lazy\">\n        <figcaption><span>Angio-TDM</span> thoracique, coupe axiale : <span>dissection aortique</span> de <strong>type A</strong> (Stanford) — double contour au sein de la lumière de l'aorte ascendante (<span>voile intimal</span> séparant vrai et faux chenal). Source : fiche source EDN item 230 — <span>Douleur thoracique</span> aiguë (Dissection aortique).</figcaption>\n      </figure><figure class=\"obj-figure\">\n        <img src=\"../assets/images/230/tdm-dissection-aortique-stanford-b.png\" alt=\"Angio-TDM thoracique en coupe axiale — dissection aortique de type B : double chenal de l&#x27;aorte descendante\" loading=\"lazy\">\n        <figcaption><span>Angio-TDM</span> thoracique, coupe axiale : dissection aortique de <strong>type B</strong> (Stanford) — double chenal limité à l'aorte descendante, l'aorte ascendante étant respectée. Source : fiche source EDN item 230 — <span>Douleur thoracique</span> aiguë (Dissection aortique).</figcaption>\n      </figure><figure class=\"obj-figure\">\n        <img src=\"../assets/images/230/classification-dissection-aortique-stanford-debakey.png\" alt=\"Schéma des classifications de Stanford et de DeBakey de la dissection aortique\" loading=\"lazy\">\n        <figcaption>Classifications de la dissection aortique. <strong>Stanford</strong> — type A : atteinte de l'aorte ascendante ; type B : aorte ascendante respectée. <strong>DeBakey</strong> — type I : porte d'entrée sur l'aorte ascendante avec extension à l'aorte descendante ; type II : limitée à l'aorte ascendante ; type III : porte d'entrée après l'artère sous-clavière gauche. Source : fiche source EDN item 230 — <span>Douleur thoracique</span> aiguë (Dissection aortique).</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Syndromes coronariens aigus, 2023</a></li></ul><p></p></details>","frequence":2},{"id":"230-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","contenu":"<div class=\"notion-course\"><p>L’ECG 12 dérivations, complété selon le contexte, est central dans l’orientation et doit être répété si les symptômes persistent ou récidivent.</p>\n      <table>\n        <thead><tr><th>Urgence</th><th>Apport de l'<span>ECG</span></th><th>Anomalies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>SCA</span> (<span>infarctus</span>)</strong></td><td>+++ (examen central)</td><td>Signes d'<span>ischémie</span> : <span>sus-décalage ST</span> ; sous-décalage ST ; anomalies de l'onde T</td></tr>\n          <tr><td><strong><span>Embolie pulmonaire</span></strong></td><td>++</td><td><span>Tachycardie sinusale</span> ; bloc de branche droit ; onde T négative ; aspect <span>S1Q3</span></td></tr>\n          <tr><td><strong>Péricardite</strong></td><td>++</td><td><span>Sus-décalage ST concave</span> vers le haut, diffus (non systématisé) et <strong>sans miroir</strong> ; <span>sous-décalage du PQ</span> ; en cas de <span>tamponnade</span> : <strong><span>microvoltage</span></strong> et <strong><span>alternance électrique</span></strong> (variation d'amplitude des QRS 1 sur 2)</td></tr>\n          <tr><td><strong><span><span>Dissection</span> aortique</span></strong></td><td>± (peu contributif)</td><td><span class=\"nc-green_bg\">Normal le plus souvent</span> ; en cas d'<span class=\"nc-red nc-bold\">extension à une artère coronaire</span> : aspect de <span><span class=\"nc-red nc-bold\">SCA</span></span> (sous-ST, sus-ST ou inversion de l'onde T)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Un <span>ECG</span> d'allure de <span><span class=\"nc-red nc-bold\">SCA</span></span> n'élimine pas une <span><span>dissection</span> aortique</span> : la dissection peut <strong>s'étendre à une coronaire</strong> et mimer un <span>infarctus</span> — d'où le risque d'anticoaguler à tort une dissection.\n      </div><div class=\"callout\"><p>Un ECG normal n’exclut ni SCA, ni EP, ni dissection. S1Q3T3 et les signes de surcharge droite sont des arguments inconstants et non spécifiques. Une péricardite peut ne pas montrer le tracé typique.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/aortic-dissection","label":"Radiopaedia : Aortic dissection"}]},{"id":"230-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","contenu":"<div class=\"notion-course\"><p>La radiographie <span class=\"nc-blue_bg\">thoracique</span> est demandée selon le contexte, notamment pour rechercher pneumothorax, pneumonie, épanchement ou congestion. Elle ne doit pas retarder la reperfusion d’un SCA ST+ et ne permet pas à elle seule d’exclure EP ou dissection.</p>\n      <table>\n        <thead><tr><th><span>Urgence</span></th><th><span>Radiographie <span class=\"nc-blue_bg\">thoracique</span></span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>SCA</span> (<span>infarctus</span>)</strong></td><td>Normale en règle (pas de signe spécifique) ; recherche de signes d'<span>insuffisance cardiaque</span></td></tr>\n          <tr><td><strong><span><span>Dissection</span> aortique</span></strong></td><td><span><span class=\"nc-blue_bg\">Élargissement du médiastin</span> supérieur</span> ++ ; ± <span>épanchement pleural</span> (hémothorax par <span><span class=\"nc-red nc-bold\">rupture</span></span> de l'aorte <span class=\"nc-blue_bg\">thoracique</span>) ; ± aspect de <span>double contour aortique</span></td></tr>\n          <tr><td><strong><span>Embolie pulmonaire</span></strong></td><td>Souvent normale ; signes inconstants et peu spécifiques</td></tr>\n          <tr><td><strong>Péricardite</strong></td><td>Normale en règle ; si <span>épanchement péricardique</span> abondant → <span>cardiomégalie avec <strong>cœur « en carafe »</strong></span> (silhouette symétrique triangulaire)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 360 — <span>Pneumothorax</span></em></p><div class=\"callout\"><p>Une tamponnade aiguë peut survenir avec un faible volume rapidement accumulé et sans cardiomégalie radiographique.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":0},{"id":"230-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","contenu":"<div class=\"notion-course\"><h4>Troponine ultrasensible</h4><ul><li>À doser devant une suspicion de SCA ; suivre le protocole validé du laboratoire (H0/H1 ou H0/H2). Une première valeur normale très précoce ne suffit pas.</li><li>Une valeur au-dessus du 99e percentile indique une <b>lésion myocardique</b>. L’infarctus requiert un contexte d’ischémie et une lésion aiguë : la cinétique seule ne prouve pas un SCA.</li><li>La troponine peut augmenter dans l’EP, la myocardite, l’IC, l’insuffisance rénale ou la dissection avec atteinte coronaire. Elle ne retarde jamais une reperfusion indiquée sur l’ECG.</li></ul><h4>D-dimères</h4><ul><li>EP : utiles pour exclure le diagnostic dans une stratégie de probabilité faible/intermédiaire ou « EP improbable ». En probabilité élevée, aller à l’imagerie appropriée.</li><li>Seuil ajusté à l’âge après 50 ans dans une stratégie validée : âge × 10 µg/L FEU ; vérifier méthode et unités. Ne pas transférer ce seuil automatiquement aux dissections.</li><li>Dissection : ils peuvent être élevés mais ne le sont pas toujours ; un résultat négatif ne rassure pas si la suspicion clinique est élevée.</li></ul><h4>Biologie complémentaire ciblée</h4><p><span class=\"nc-blue_bg\">NFS</span>-<span class=\"nc-blue_bg\">plaquettes</span>, ionogramme, créatinine, hémostase et groupage selon gravité et geste attendu. Lactate si hypoperfusion ; <span class=\"nc-blue_bg\">CRP</span> selon contexte inflammatoire. CK si suspicion d’ischémie musculaire/rhabdomyolyse, sans retarder l’imagerie.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Syndromes coronariens aigus, 2023</a></li></ul><p></p></details>","frequence":0},{"id":"230-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place de la coronarographie dans le diagnostic et les principes de prise en charge du syndrome coronarien aigu","contenu":"<div class=\"notion-course\"><h4>Coronarographie : diagnostic et revascularisation</h4><p>Elle visualise les coronaires et permet une angioplastie avec stent si indiquée. L’orientation est décidée avec la filière cardiologique, en privilégiant l’abord radial lorsque possible.</p><table><thead><tr><th>Situation</th><th>Stratégie</th></tr></thead><tbody><tr><td>SCA ST+ ou équivalent d’occlusion</td><td>Reperfusion immédiate. Angioplastie primaire si passage du guide réalisable dans les 120 min après le diagnostic.</td></tr><tr><td>Délai d’angioplastie supérieur à 120 min</td><td>Si symptômes depuis moins de 12 h et sans contre-indication : fibrinolyse sans délai, puis transfert immédiat vers un centre d’angioplastie. Échec : angioplastie de sauvetage ; succès : coronarographie dans les 2–24 h.</td></tr><tr><td>Présentation au-delà de 12 h</td><td>Angioplastie urgente si ischémie persistante ou instabilité ; stratégie spécialisée selon délai, symptômes et myocarde à risque.</td></tr><tr><td>SCA sans sus-ST, très haut risque</td><td>Coronarographie immédiate : choc/instabilité, douleur réfractaire, arythmie menaçante, complication mécanique ou IC liée à une ischémie persistante.</td></tr><tr><td>SCA sans sus-ST, haut risque</td><td>Stratégie invasive hospitalière ; coronarographie précoce dans les 24 h à envisager, notamment si GRACE &gt; 140. Les autres patients relèvent d’une stratification individualisée.</td></tr></tbody></table><p>Aspirine et anticoagulation selon stratégie ; choix du P2Y12 et moment de son administration selon contexte. Pas de prétraitement P2Y12 systématique dans un SCA non ST+ lorsque l’anatomie est inconnue et une coronarographie précoce prévue. Pas de fibrinolyse dans le SCA non ST+. Voir l’item 339 pour les détails.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-05-item-339-syndromes-coronariens-aigus/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Syndromes coronariens aigus</a></li><li><a href=\"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/\" target=\"_blank\" rel=\"noopener noreferrer\">ESC · Syndromes coronariens aigus, 2023</a></li></ul><p></p></details>","frequence":1},{"id":"230-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place de l’échocardiographie","contenu":"<div class=\"notion-course\"><p>L'<span>échocardiographie transthoracique (ETT)</span> est un examen <strong>non invasif, réalisable au lit du patient</strong>, précieux dans le bilan d'une <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span> aiguë. L'<span>échocardiographie transœsophagienne (ETO)</span> est plus performante pour explorer l'aorte.</p>\n      <table>\n        <thead><tr><th><span>Urgence</span></th><th>Apport de l'<span>échocardiographie</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span>Dissection</span> aortique</span></strong></td><td><span>ETO</span> surtout : visualisation du <strong><span>voile intimal</span></strong>, signe <span>pathognomonique</span> ; chez un patient stable à faible probabilité, l'<span><span class=\"nc-blue_bg\">ETT</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">ETO</span></span> peut poser le diagnostic</td></tr>\n          <tr><td><strong>Péricardite</strong></td><td>Recherche et quantification d'un <span>épanchement péricardique</span> ; <span>dépistage</span> d'une <span>tamponnade</span></td></tr>\n          <tr><td><strong><span>Embolie pulmonaire</span></strong></td><td>Recherche d'un retentissement sur le <span>cœur droit</span> (dilatation du ventricule droit, cœur pulmonaire aigu) — intérêt pronostique</td></tr>\n          <tr><td><strong><span>SCA</span> (<span>infarctus</span>)</strong></td><td>Recherche de <span>troubles de la cinétique segmentaire</span> ; évaluation de la fonction ventriculaire gauche</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 235 — Péricardite aiguë</em></p><div class=\"callout\"><p>Une ETT normale n’exclut pas SCA, EP ou dissection. La tamponnade est une urgence hémodynamique, pas un simple seuil de volume. L’ETO est ciblée ; elle ne remplace pas systématiquement l’<span class=\"nc-blue_bg\">angio-TDM</span> aortique chez un patient stable.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":0},{"id":"230-12","rang":"B","rubrique":"Étiologies","titre":"Devant un angor d’effort, connaître les principales causes d’angor fonctionnel","contenu":"<div class=\"notion-course\"><p>L’angor fonctionnel traduit un déséquilibre entre apports et besoins myocardiques en oxygène. Il peut survenir sans sténose coronaire significative, mais un facteur fonctionnel peut aussi aggraver une coronaropathie préexistante.</p>\n      <p>Devant un <span>angor</span> d'effort, les principales causes d'angor fonctionnel — entrant dans le cadre des <strong>douleurs chroniques de cause cardiaque</strong> — sont :</p>\n      <table>\n        <thead><tr><th>Cause</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-brown_bg\">Anémie</span></span></td><td>Baisse du transport de l'oxygène</td></tr>\n          <tr><td><span>Tachycardies</span> (ex. <span><span class=\"nc-brown_bg\">fibrillation atriale</span></span>)</td><td>Augmentation des besoins myocardiques + raccourcissement de la diastole</td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Hyperthyroïdie</span></span></td><td>Augmentation du débit cardiaque et de la consommation d'oxygène</td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Rétrécissement aortique serré</span></span></td><td><span>Angor</span> d'effort par obstacle à l'éjection ventriculaire</td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Cardiomyopathie hypertrophique</span></span></td><td>Douleur d'effort par inadéquation de la perfusion d'un myocarde épaissi</td></tr>\n          <tr><td><span>HTAP sévère</span></td><td>Souffrance <span>ischémique</span> du ventricule droit lorsque la pression intraventriculaire droite dépasse la pression de perfusion coronarienne</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — <span class=\"nc-brown_bg\">Anémie</span> · 232 — <span><span class=\"nc-brown_bg\">Fibrillation atriale</span></span> · 242 — <span><span class=\"nc-brown_bg\">Hyperthyroïdie</span></span> · 233 — Valvulopathie</em></p><p>Un angor sans obstruction coronaire peut aussi relever d’un spasme ou d’une dysfonction microvasculaire (ANOCA/INOCA), à explorer selon le contexte cardiologique.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":0},{"id":"230-13","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","contenu":"<div class=\"notion-course\"><p>En dehors des 4 urgences cardio-vasculaires, de nombreuses causes <strong>thoraciques</strong> de douleur aiguë doivent être connues. Elles se répartissent par appareil.</p>\n      <table>\n        <thead><tr><th>Origine</th><th>Causes et particularités sémiologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Respiratoire</strong></td>\n            <td>\n              <strong>Pleuro-pulmonaire :</strong> <span>pneumothorax</span> ; <span>épanchement pleural</span> ; <span>pneumopathie infectieuse</span> (douleur intense « en coup de poignard » de type pleural en cas de réaction pleurale)\n              <ul style=\"margin:4px 0 0;padding-left:18px\">\n                <li><span>Pneumothorax</span> — <span>douleur de type pleural</span> (latéro-<span class=\"nc-blue_bg\">thoracique</span>, majorée à l'inspiration).</li>\n                <li><span>Tympanisme à la percussion</span> + <span>abolition du murmure vésiculaire</span> du côté atteint.</li>\n                <li>Diagnostic : <span>radiographie <span class=\"nc-blue_bg\">thoracique</span></span> de face en <strong>inspiration</strong> (hyperclarté + ligne pleurale ; le cliché en expiration n'est plus recommandé).</li>\n              </ul><br>\n              <strong><span>Trachéobronchite aiguë</span> :</strong> <span>brûlure respiratoire</span> à chaque mouvement, <strong>aggravée par la <span>toux</span></strong>, initialement sèche ; cortège <span>viral</span> fréquent ; traitement symptomatique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Œsophagienne</strong></td>\n            <td>RGO/œsophagite et <span class=\"nc-orange_bg\">spasme œsophagien</span> peuvent imiter un angor et être sensibles aux nitrés. Boerhaave : douleur intense après vomissements, dyspnée et parfois emphysème sous-cutané/pneumomédiastin ; urgence. Le syndrome de Mallory-Weiss se manifeste surtout par une hématémèse après vomissements ; une douleur <span class=\"nc-blue_bg\">thoracique</span> intense après vomissements fait rechercher une <span class=\"nc-red nc-bold\">rupture</span> œsophagienne.</td>\n          </tr>\n          <tr>\n            <td><strong>Musculo-squelettique</strong></td>\n            <td>\n              <strong><span><span class=\"nc-orange_bg\">Syndrome de Tietze</span></span> :</strong> inflammation du cartilage à la jonction du sternum et d'une ou plusieurs côtes — <span>douleur reproduite par la palpation</span><br>\n              <strong>Osseuse :</strong> lésions sternales, <span>arthralgies</span> chondro-costales ; fractures costales, parfois pathologiques (<span>métastases</span>, <span>myélome multiple</span>)<br>\n              <strong>Douleur musculo-ligamentaire</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Neurologique</strong></td>\n            <td><span>Zona intercostal</span> ; <span>tassement vertébral</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Toxique</span> — cocaïne</strong></td>\n            <td><span><span class=\"nc-red_bg\">SCA</span></span> voire <span>coronarospasme</span> (<span>angor</span> de Prinzmetal) ; <span><span class=\"nc-red_bg\">myopéricardite</span></span> ; <span>pneumothorax</span> lié aux efforts inspiratoires (sniff)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une douleur œsophagienne (RGO, spasme) peut <strong>parfaitement mimer un <span><span class=\"nc-red_bg\">SCA</span></span></strong> et même être <strong><span class=\"nc-green_bg\">calmée par les dérivés </span><span><span class=\"nc-green_bg\">nitrés</span></span></strong>. On ne retient jamais une cause œsophagienne <strong>avant d'avoir éliminé un <span><span class=\"nc-red_bg\">SCA</span></span></strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 360 — <span>Pneumothorax</span> · 154 — Infection bronchopulmonaire communautaire · 271 — RGO - hernie hiatale</em></p><div class=\"callout\"><p>Pneumothorax compressif avec détresse : décompression urgente sans attendre la radiographie. Boerhaave : avis chirurgical urgent et imagerie adaptée. Une douleur reproductible à la palpation ne suffit pas à exclure un SCA.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":2},{"id":"230-14","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes extra-thoraciques de douleur thoracique","contenu":"<div class=\"notion-course\"><p>Une <span>douleur <span class=\"nc-blue_bg\">thoracique</span></span> peut avoir une origine <strong>extra-<span class=\"nc-blue_bg\">thoracique</span></strong> — la connaître évite des explorations cardiaques inutiles, une fois les urgences écartées.</p>\n      <table>\n        <thead><tr><th>Origine</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Abdominale</strong> (douleur projetée)</td>\n            <td><span>Lithiase vésiculaire</span> ; <span>ulcère gastro-duodénal</span> ; <span>pancréatite aiguë</span> ; <span>appendicite sous-hépatique</span> ; <span>abcès sous-phrénique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Psychogène</strong></td>\n            <td>Douleurs associées à une anxiété ou à une attaque de panique ; rechercher positivement le tableau tout en évaluant les causes organiques selon le contexte.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div>Une cause anxieuse se retient après une évaluation adaptée, sans assimiler d’emblée angoisse et absence de maladie organique. Les deux peuvent coexister.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span>Douleur abdominale</span> aiguë · 358 — <span>Pancréatite aiguë</span> · 277 — Lithiase biliaire · 272 — Ulcère gastroduodénal - gastrite</em></p></div><details><summary>Sources et compléments</summary><p>Relecture du 15 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleur thoracique (230)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418154ad5ce741c487f5e8?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dissection aortique</a></li><li><a href=\"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/\" target=\"_blank\" rel=\"noopener noreferrer\">CNEC · Douleur thoracique aiguë</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"PIED ne couvre pas tout","contenu":"<div class=\"notion-course\"><p>Rechercher aussi pneumothorax compressif et <span class=\"nc-red nc-bold\">rupture</span> œsophagienne.</p></div>"},{"type":"piege","titre":"Un examen normal ne suffit pas","contenu":"<div class=\"notion-course\"><p>ECG, radiographie ou échographie peuvent être normaux malgré une urgence.</p></div>"},{"type":"piege","titre":"Deux chronomètres","contenu":"<div class=\"notion-course\"><p>La fenêtre de fibrinolyse part des symptômes ; les 120 min d’angioplastie partent du diagnostic.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Évaluer les défaillances et appeler la filière adaptée.</li><li>ECG et examens ciblés ; interpréter troponine et D-dimères avec leur contexte.</li><li>Réévaluer les hypothèses si discordance.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Traiter les défaillances pendant le bilan.</li><li>Reperfuser un SCA éligible sans attendre la troponine.</li><li>Avis aortique si dissection ; éviter les antithrombotiques empiriques en attendant.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>ECG 12 dérivations puis compléments ciblés.</li><li><span class=\"nc-blue_bg\">Angio-TDM</span> aortique si suspicion significative et patient transportable.</li><li>Échographie au lit en cas d’instabilité.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-06-item-230-douleur-thoracique-aigue/","label":"CNEC · Douleur thoracique aiguë ↗"},{"href":"https://www.erc.edu/science-research/guidelines/guidelines-2025/guidelines-2025-english/","label":"ERC · Réanimation, recommandations 2025 ↗"},{"href":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","label":"ESC · Syndromes coronariens aigus, 2023 ↗"},{"href":"https://www.sfcardio.fr/publication/chapitre-05-item-339-syndromes-coronariens-aigus/","label":"CNEC · Syndromes coronariens aigus ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Détresse ou menace immédiate ?","detail":"<ul><li>Constantes, respiration, conscience, perfusion ; ECG précoce.</li></ul>","branches":[{"label":"Oui","to":"stabiliser"},{"label":"Non","to":"orienter"}]},{"id":"stabiliser","kind":"urgent","label":"Alerte et stabilisation sans délai","detail":"<ul><li>Filière urgente et traitement de la cause ; bilan en parallèle.</li></ul>","branches":[{"label":"Orientation dès que possible","to":"orienter"}]},{"id":"orienter","kind":"decision","label":"Quel diagnostic grave évoquer ?","detail":"<ul><li>Plusieurs hypothèses peuvent coexister ; un ECG normal ne suffit pas.</li></ul>","branches":[{"label":"SCA / ischémie","to":"coronaire"},{"label":"Syndrome aortique","to":"aorte"},{"label":"EP / péricarde","to":"autrescv"},{"label":"Autre présentation","to":"autres"}]},{"id":"coronaire","kind":"urgent","label":"ECG répétés et stratégie coronaire","detail":"<ul><li>ST+ ou équivalent : reperfusion ; sinon troponines selon protocole validé.</li></ul>","branches":[{"label":"Filière adaptée","to":"filiere"}]},{"id":"aorte","kind":"urgent","label":"Rechercher dissection et complications","detail":"<ul><li>Douleur brutale, asymétrie, souffle, déficit ; angio-TDM si état compatible.</li><li>Ne pas administrer réflexivement des antithrombotiques avant d’évaluer une suspicion de dissection.</li></ul>","branches":[{"label":"Avis aortique urgent","to":"filiere"}]},{"id":"autrescv","kind":"decision","label":"Choisir le bilan de l’hypothèse","detail":"<ul><li>EP : probabilité puis D-dimères/imagerie si indiqué ; péricarde : ETT, tamponnade ?</li></ul>","branches":[{"label":"Gravité / diagnostic retenu","to":"filiere"},{"label":"Hypothèse non confirmée","to":"autres"}]},{"id":"filiere","kind":"urgent","label":"Traitement et orientation spécifiques","detail":"<ul><li>USIC, réanimation, chirurgie ou autre filière selon cause et gravité.</li></ul>","branches":[]},{"id":"autres","kind":"decision","label":"Cause thoracique ou extra-thoracique ?","detail":"<ul><li>Pneumothorax, infection, œsophage, paroi, neurologique ; gravité propre à chaque cause.</li></ul>","branches":[{"label":"Cause identifiée","to":"specifique"},{"label":"Angor d’effort / déséquilibre","to":"fonctionnel"},{"label":"Doute persistant","to":"revoir"}]},{"id":"fonctionnel","kind":"finish","label":"Rechercher facteurs d’ischémie et coronaropathie","detail":"<ul><li>Anémie, tachycardie, valvulopathie, hypoxémie ; mécanismes associés possibles.</li></ul>","branches":[]},{"id":"specifique","kind":"finish","label":"Traiter et organiser la surveillance","detail":"<ul><li>Consignes de réévaluation selon diagnostic et évolution.</li></ul>","branches":[]},{"id":"revoir","kind":"uncertain","label":"Réévaluer sans fausse réassurance","detail":"<ul><li>Examens répétés/complémentaires selon clinique et chronologie.</li></ul>","branches":[]}]},"cards":[{"i":"386201edcbce","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’une douleur thoracique aiguë","q":"Quelles structures peuvent provoquer une douleur thoracique et quelles causes sont fréquentes ?","a":"<div class=\"notion-course\"><ul><li>Paroi, plèvre, péricarde, cœur, œsophage, aorte.</li><li>Causes fréquentes : pariétales, digestives, anxieuses et coronariennes ; proportions variables selon le lieu de consultation. Priorité : rechercher les urgences.</li></ul></div>"},{"i":"40b4e18c2a76","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’une douleur thoracique aiguë","q":"Quelle est la définition d'une douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>La douleur <span class=\"nc-blue_bg\">thoracique</span> aiguë (DTA) est une douleur ressentie dans la <strong>région du thorax</strong>, d'<strong>installation récente</strong>.</p></div>"},{"i":"5cf06b8caf64","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’une douleur thoracique aiguë","q":"Le parenchyme pulmonaire peut-il être directement à l'origine d'une douleur thoracique aiguë ? Pourquoi ?","a":"<div class=\"notion-course\"><p>Non, le <strong>parenchyme pulmonaire ne fait pas mal</strong> directement car il n'est pas innervé pour la douleur. Seules les pathologies pulmonaires atteignant la <strong>plèvre</strong> peuvent être sources de douleur <span class=\"nc-blue_bg\">thoracique</span>.</p></div>"},{"i":"b10df238011a","n":230,"o":"230-1","u":"Définition","t":"Connaître la définition d’une douleur thoracique aiguë","q":"Quel est l'objectif prioritaire de la prise en charge initiale d'une douleur thoracique aiguë aux urgences ?","a":"<div class=\"notion-course\"><p>L'objectif prioritaire est d'<strong>éliminer une urgence vitale</strong>.</p></div>"},{"i":"127fa328f868","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes musculo-squelettiques de douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>Les causes musculo-squelettiques de douleur <span class=\"nc-blue_bg\">thoracique</span> aiguë comprennent :</p><ul><li>Le <strong><span class=\"nc-orange_bg\">syndrome de Tietze</span></strong> : inflammation du cartilage à la jonction du sternum et d'une ou plusieurs côtes, avec douleur <strong>reproduite par la palpation</strong>.</li><li>Les <strong>lésions osseuses</strong> : lésions sternales, arthralgies chondro-costales, fractures costales (éventuellement pathologiques comme des <strong>métastases</strong> ou un <strong>myélome multiple</strong>).</li><li>Les <strong>douleurs musculo-ligamentaires</strong>.</li></ul></div>"},{"i":"1b8c0c6ae830","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes respiratoires pleuro-pulmonaires de douleur thoracique aiguë, en dehors des urgences cardiovasculaires ?","a":"<div class=\"notion-course\"><p>Les causes respiratoires pleuro-pulmonaires incluent :</p><ul><li>Le <strong>pneumothorax</strong>.</li><li>L'<strong>épanchement pleural</strong>.</li><li>La <strong>pneumopathie infectieuse</strong>, pouvant causer une douleur intense « en <span class=\"nc-red nc-bold\">coup de poignard</span> » de type pleural en cas de réaction pleurale.</li><li>La <strong><span class=\"nc-orange_bg\">trachéobronchite aiguë</span></strong>.</li></ul></div>"},{"i":"5b8290c186a2","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes œsophagiennes de douleur thoracique aiguë et leurs particularités sémiologiques ?","a":"<div class=\"notion-course\"><ul><li>RGO/œsophagite, <span class=\"nc-orange_bg\">spasme œsophagien</span> : peuvent mimer un angor et répondre aux nitrés.</li><li>Boerhaave : douleur intense après vomissements, dyspnée, parfois emphysème ; urgence.</li><li>Mallory-Weiss : surtout hématémèse après vomissements.</li></ul></div>"},{"i":"647ff8b4b651","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Comment diagnostique-t-on un pneumothorax ?","a":"<div class=\"notion-course\"><p>Chez un patient stable : radiographie en inspiration ou échographie selon contexte. Hyperclarté et ligne pleurale orientent. Si pneumothorax compressif avec détresse, décompression urgente sans attendre l’imagerie.</p></div>"},{"i":"9d65d7f8c40e","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quel est le piège diagnostique classique concernant la douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>Le piège classique est qu'une douleur d'origine œsophagienne (RGO, spasme) peut parfaitement mimer un <strong>syndrome coronarien aigu (SCA)</strong> et même être <span class=\"nc-green_bg\">calmée par les </span><strong><span class=\"nc-green_bg\">dérivés nitrés</span></strong>. Il est impératif de <strong>toujours éliminer un SCA</strong> avant de conclure à une cause œsophagienne.</p></div>"},{"i":"bc34ff30667d","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les caractéristiques de la douleur thoracique aiguë en cas de pneumothorax ?","a":"<div class=\"notion-course\"><p>La douleur du pneumothorax est de type <strong>pleural</strong>, c'est-à-dire :</p><ul><li><strong>Latéro-<span class=\"nc-blue_bg\">thoracique</span></strong>.</li><li><strong>Majorée à l'inspiration</strong>.</li></ul><p>À l'examen clinique, on retrouve un <strong>tympanisme</strong> à la percussion et une <strong>abolition du murmure vésiculaire</strong> du côté atteint.</p></div>"},{"i":"cefca07d068e","n":230,"o":"230-13","u":"Étiologies","t":"Connaître les principales causes thoraciques de douleur aiguë en dehors des quatre urgences cardio-vasculaires","q":"Quelles sont les causes neurologiques et toxiques de douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>Les causes neurologiques sont le <strong>zona intercostal</strong> et le <strong>tassement vertébral</strong>. La consommation de <strong>cocaïne</strong> est la principale cause toxique, pouvant entraîner un <span class=\"nc-red_bg\">SCA</span>, un coronarospasme (<strong>angor de Prinzmetal</strong>), une <span class=\"nc-red_bg\">myopéricardite</span> ou un pneumothorax lié aux efforts inspiratoires (sniff).</p></div>"},{"i":"07556cb34a16","n":230,"o":"230-14","u":"Étiologies","t":"Connaître les principales causes extra-thoraciques de douleur thoracique","q":"Qu'est-ce qu'une douleur thoracique d'origine extra-thoracique ?","a":"<div class=\"notion-course\"><p>Une douleur <span class=\"nc-blue_bg\">thoracique</span> d'origine extra-<span class=\"nc-blue_bg\">thoracique</span> est une sensation douloureuse ressentie au niveau du thorax, mais dont la cause initiale ou le processus pathologique provient d'organes ou de structures situées <strong>en dehors de la paroi <span class=\"nc-blue_bg\">thoracique</span> et des organes intrathoraciques</strong> (cœur, poumons, œsophage). Il ne s'agit donc pas d'une atteinte directe de ces derniers.</p></div>"},{"i":"8a9ba5c9d53d","n":230,"o":"230-14","u":"Étiologies","t":"Connaître les principales causes extra-thoraciques de douleur thoracique","q":"Quel est le rôle des douleurs psychogènes en tant que cause de douleur thoracique, et comment sont-elles diagnostiquées ?","a":"<div class=\"notion-course\"><p>Anxiété et attaque de panique peuvent provoquer une douleur <span class=\"nc-blue_bg\">thoracique</span>, mais peuvent aussi accompagner une urgence organique. Évaluer le risque et rechercher positivement les éléments du trouble anxieux sans conclusion prématurée.</p></div>"},{"i":"b0331bd21a6b","n":230,"o":"230-14","u":"Étiologies","t":"Connaître les principales causes extra-thoraciques de douleur thoracique","q":"Quelles sont les principales causes abdominales pouvant provoquer une douleur thoracique projetée ?","a":"<div class=\"notion-course\"><ul><li><strong>Lithiase vésiculaire</strong></li><li><strong>Ulcère gastro-duodénal</strong></li><li><strong>Pancréatite aiguë</strong></li><li><strong>Appendicite sous-hépatique</strong></li><li><strong>Abcès sous-phrénique</strong></li></ul></div>"},{"i":"0812bdc6e34e","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quelle est la première étape impérative devant toute douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>La première étape impérative, avant même de rechercher la cause, est de rechercher une <strong>détresse vitale</strong> par un examen rapide et systématisé.</p></div>"},{"i":"3983ada54283","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quels sont les signes à rechercher devant une suspicion de détresse respiratoire lors d'une douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><ul><li><strong>Fréquence respiratoire</strong> : polypnée (&gt; 30/min) ou bradypnée (&lt; 10/min), voire pause respiratoire.</li><li><strong>Lutte respiratoire</strong> : tirage avec mise en jeu des muscles respiratoires accessoires.</li><li><strong>Retentissement</strong> : sueurs, cyanose, désaturation (<strong>SpO₂ &lt; 90 %</strong>), encéphalopathie respiratoire.</li></ul></div>"},{"i":"7f0ec527da8b","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Que doit entraîner la découverte d'un seul signe de détresse vitale devant une douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>La présence d'un seul de ces signes impose une <strong>prise en charge immédiate</strong> en <strong>salle d'accueil des urgences vitales (SAUV)</strong> ou en réanimation, sans attendre les résultats paracliniques.</p></div>"},{"i":"bc9c6800184b","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quels sont les signes à rechercher devant une suspicion d'atteinte neurologique lors d'une douleur thoracique aiguë, indiquant une détresse vitale ?","a":"<div class=\"notion-course\"><ul><li><strong>Troubles de la conscience</strong> : confusion, agitation, convulsions.</li></ul></div>"},{"i":"d0d2f505b8c7","n":230,"o":"230-2","u":"Identifier une urgence","t":"Savoir rechercher une détresse vitale devant une douleur thoracique","q":"Quels sont les signes à rechercher devant une suspicion de détresse hémodynamique lors d'une douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><ul><li>Arrêt : inconscience et respiration absente/anormale ; pouls central recherché au plus 10 s par le soignant.</li><li>Choc : hypoperfusion, extrémités froides, marbrures, oligurie, troubles de conscience ; hypotension fréquente mais non obligatoire.</li><li>Pouls paradoxal : baisse inspiratoire de PAS &gt; 10 mmHg ; rechercher aussi turgescence jugulaire.</li></ul></div>"},{"i":"3f0e356d4a32","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quels sont les signes de gravité et la décision thérapeutique immédiate en cas de dissection aortique de type A ?","a":"<div class=\"notion-course\"><ul><li>Douleur brutale, asymétrie des pouls/PA, insuffisance aortique, déficit ou choc évoquent une dissection, sans être obligatoires.</li><li>Type A : avis et chirurgie urgents. Éviter l’anticoagulation/fibrinolyse empirique tant que la suspicion n’est pas clarifiée.</li></ul></div>"},{"i":"4bde727fd742","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quelle est la conduite à tenir devant un état de choc ou une hypotension persistante lors d'une douleur thoracique grave ?","a":"<div class=\"notion-course\"><p>Devant un état de <strong>choc</strong> ou une <strong>hypotension persistante</strong> lors d'une douleur <span class=\"nc-blue_bg\">thoracique</span> grave, la conduite à tenir est l'<strong>orientation en réanimation</strong> et un <strong>traitement étiologique</strong> sans délai.</p></div>"},{"i":"a591aaa24084","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quel signe de gravité oriente vers une tamponnade cardiaque et quelle est la décision thérapeutique immédiate ?","a":"<div class=\"notion-course\"><p>Le signe de gravité orientant vers une <strong>tamponnade cardiaque</strong> est l'association <strong>pouls paradoxal</strong>, <strong>turgescence jugulaire</strong> et <strong>hypotension</strong>. La décision thérapeutique immédiate est un <strong>drainage péricardique en urgence</strong>.</p></div>"},{"i":"de6f099af09c","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quelle est la décision thérapeutique immédiate en cas de pouls non perçu et d'inconscience (arrêt circulatoire) devant une douleur thoracique grave ?","a":"<div class=\"notion-course\"><p>En cas d'<strong>arrêt circulatoire</strong> (pouls non perçu, inconscience) devant une douleur <span class=\"nc-blue_bg\">thoracique</span> grave, la décision thérapeutique immédiate est la <strong>réanimation cardio-pulmonaire</strong> et l'appel du réanimateur.</p></div>"},{"i":"df0d1a15c4c1","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quelle est la prise en charge immédiate devant une douleur thoracique avec signes de gravité, avant même le diagnostic étiologique ?","a":"<div class=\"notion-course\"><p>Devant une douleur <span class=\"nc-blue_bg\">thoracique</span> avec signes de gravité, la prise en charge immédiate, menée en parallèle de l'évaluation, comprend :</p><ul><li>Mise en condition immédiate avec <strong>scope ECG continu</strong>, monitorage de la <strong>pression artérielle</strong> et de la <strong>SpO₂</strong>.</li><li>Pose d'une <strong>voie veineuse périphérique</strong>.</li><li><strong>Oxygénothérapie</strong> en cas de désaturation.</li><li>Prise en charge en salle d'accueil des urgences vitales (<strong>SAUV</strong>), à proximité immédiate d'un <strong>chariot d'urgence</strong> et d'un <strong>défibrillateur</strong>.</li></ul></div>"},{"i":"e20995ab2899","n":230,"o":"230-3","u":"Identifier une urgence","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quels sont les signes de gravité généraux d'une douleur thoracique aiguë nécessitant des décisions thérapeutiques immédiates ?","a":"<div class=\"notion-course\"><p>Les signes de gravité généraux d'une douleur <span class=\"nc-blue_bg\">thoracique</span> aiguë nécessitant des décisions thérapeutiques immédiates sont les signes de <strong>détresse vitale</strong> :</p><ul><li><strong>Détresse respiratoire</strong></li><li><strong>Détresse hémodynamique</strong></li><li><strong>Détresse neurologique</strong></li></ul></div>"},{"i":"29beedf231fa","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quels sont les principaux critères permettant de distinguer sémiologiquement une douleur thoracique d'origine ischémique (syndrome coronarien aigu) d'une douleur non ischémique ?","a":"<div class=\"notion-course\"><p>La distinction sémiologique entre une douleur ischémique et non ischémique repose sur les critères suivants :</p><ul><li><strong>Caractéristiques</strong> :<ul><li><strong>Ischémique</strong> : <strong>constriction</strong>, <strong>pesanteur</strong>, brûlure.</li><li><strong>Non ischémique</strong> : acérée, en <span class=\"nc-red nc-bold\">coup de poignard</span>, augmentée par la respiration.</li></ul></li><li><strong>Siège et irradiation</strong> :<ul><li><strong>Ischémique</strong> : <strong>rétrosternal</strong>, médiothoracique, irradiant cou, épaules, avant-bras, mâchoire ; souvent associé à <strong>sueurs</strong> et <strong>nausées</strong>.</li><li><strong>Non ischémique</strong> : sous-mammaire gauche, hémithorax gauche, punctiforme (montré du doigt) ; dorsal (suggérant une dissection).</li></ul></li><li><strong>Facteurs déclenchants</strong> :<ul><li><strong>Ischémique</strong> : <strong>effort</strong>, stress, énervement, temps froid.</li><li><strong>Non ischémique</strong> : après la fin de l'effort, soulagement par l'effort, ou provoquée par un mouvement particulier du corps.</li></ul></li><li><strong>Durée</strong> :<ul><li><strong>Ischémique</strong> : <strong>minutes</strong>.</li><li><strong>Non ischémique</strong> : <strong>secondes</strong>, ou heures (en l'absence d'élévation des troponines).</li></ul></li></ul><div class=\"callout\"><p>Ce sont des orientations probabilistes. Aucun caractère de douleur ne suffit à exclure un SCA ; une douleur dorsale peut correspondre à une dissection grave.</p></div></div>"},{"i":"58e83eb42bf0","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer une dissection aortique, en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<div class=\"notion-course\"><p>Le profil clinique évocateur d'une <strong>dissection aortique</strong> est le suivant :</p><ul><li><strong>Terrain</strong> : Présence de <strong>FDR cardiovasculaires</strong>, particulièrement l'<strong>HTA</strong> (hypertension artérielle).</li><li><strong>Mode de survenue</strong> : <strong>Brutal</strong>.</li><li><strong>Horaire</strong> : Généralement au repos.</li><li><strong>Localisation et irradiation</strong> : Douleur <strong>rétrosternale</strong>, souvent <strong>transfixiante</strong> (irradiant dans le <span class=\"nc-blue_bg\">dos</span>).</li><li><strong>Type</strong> : Douleur en <strong><span class=\"nc-red nc-bold\">coup de poignard</span></strong>.</li></ul></div>"},{"i":"677623c9ded4","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer une embolie pulmonaire, en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<div class=\"notion-course\"><ul><li>Terrain thromboembolique : antécédent, immobilisation/chirurgie, cancer, grossesse/post-partum, œstrogènes.</li><li>Dyspnée et douleur souvent pleurale latéro/basithoracique, d’installation brutale ou progressive ; parfois syncope ou hémoptysie. Aucun profil n’est obligatoire.</li></ul></div>"},{"i":"7c6c692aa2b0","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer un Syndrome Coronarien Aigu (SCA), en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<div class=\"notion-course\"><p>Le profil clinique évocateur d'un <strong>Syndrome Coronarien Aigu (SCA)</strong> est le suivant :</p><ul><li><strong>Terrain</strong> : Présence de <strong>FDR cardiovasculaires</strong> (facteurs de risque).</li><li><strong>Mode de survenue</strong> : Généralement <strong>brutal</strong>.</li><li><strong>Horaire</strong> : Peut survenir à l'effort ou au repos.</li><li><strong>Localisation et irradiation</strong> : Douleur <strong>rétrosternale</strong>, pouvant irradier à l'épigastre, la mâchoire, les bras ou être interscapulaire.</li><li><strong>Type</strong> : Douleur <strong>constrictive</strong> ou de type <strong>brûlure</strong>.</li></ul></div>"},{"i":"aec287e91eeb","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Face à une douleur thoracique aiguë, quelles sont les quatre urgences cardiovasculaires vitales à évoquer systématiquement, selon le moyen mnémotechnique PIED ?","a":"<div class=\"notion-course\"><p>Devant une douleur <span class=\"nc-blue_bg\">thoracique</span> aiguë, les <strong>quatre urgences cardiovasculaires vitales</strong> à évoquer systématiquement, regroupées sous le moyen mnémotechnique PIED, sont :</p><ul><li><strong>P</strong> : <strong>Péricardite</strong></li><li><strong>I</strong> : <strong>Infarctus</strong> (syndrome coronarien aigu - SCA)</li><li><strong>E</strong> : <strong>Embolie pulmonaire</strong></li><li><strong>D</strong> : <strong>Dissection aortique</strong></li></ul></div>"},{"i":"cdf8f6250822","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quel profil clinique doit faire évoquer une péricardite, en termes de terrain, mode de survenue, horaire, localisation et type de douleur ?","a":"<div class=\"notion-course\"><p>Le profil clinique évocateur d'une <strong>péricardite</strong> est le suivant :</p><ul><li><strong>Terrain</strong> : Généralement <strong>sujet jeune</strong>, souvent précédé d'un <strong>contage viral</strong>.</li><li><strong>Mode de survenue</strong> : <strong>Aigu</strong>.</li><li><strong>Horaire</strong> : Souvent aggravée à l'inspiration et en décubitus.</li><li><strong>Localisation et irradiation</strong> : Douleur <strong>rétrosternale</strong>.</li><li><strong>Type</strong> : Douleur de type <strong>constrictive</strong>.</li></ul></div>"},{"i":"ed4aa35c8c3f","n":230,"o":"230-4","u":"Diagnostic positif","t":"Savoir évoquer les quatre urgences cardio-vasculaires devant une douleur thoracique","q":"Quelles sont les plaintes cardinales qu'il est indispensable de renseigner systématiquement pour toute urgence cardiovasculaire devant une douleur thoracique ?","a":"<div class=\"notion-course\"><p>Indépendamment de l'urgence cardiovasculaire évoquée devant une douleur <span class=\"nc-blue_bg\">thoracique</span>, quatre plaintes cardinales doivent être systématiquement renseignées :</p><ul><li>La <strong>douleur <span class=\"nc-blue_bg\">thoracique</span></strong> elle-même.</li><li>La <strong>dyspnée</strong>.</li><li>La <strong>syncope</strong>.</li><li>Les <strong>palpitations</strong>.</li></ul></div>"},{"i":"1fa618406c45","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","q":"Quels sont les signes physiques à rechercher lors de l'examen clinique d'une dissection aortique ?","a":"<div class=\"notion-course\"><p>Les signes physiques d'une dissection aortique sont :</p><ul><li>Une <strong><span class=\"nc-yellow_bg\">asymétrie tensionnelle</span></strong> (différence &gt; <strong>20 mmHg</strong> entre les deux bras).</li><li>L'<strong><span class=\"nc-yellow_bg\">abolition d'un pouls</span></strong>.</li><li>Un <strong><span class=\"nc-yellow_bg\">souffle d'insuffisance aortique</span></strong> (présent dans <strong>50 % des dissections de type A</strong>).</li><li>Une <strong><span class=\"nc-orange_bg\">poussée d'HTA</span></strong> ou, au contraire, une <strong>hypotension/choc</strong>.</li></ul></div>"},{"i":"2374757417bb","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","q":"Quelles sont les complications possibles d'une dissection aortique, parfois révélatrices ?","a":"<div class=\"notion-course\"><p>Les complications, parfois révélatrices, d'une dissection aortique par extension du <span class=\"nc-brown_bg\">faux chenal</span> aux collatérales sont :</p><ul><li>Un <strong><span class=\"nc-red_bg\">déficit neurologique</span></strong> (AVC).</li><li>Un <strong><span class=\"nc-red_bg\">infarctus médullaire</span></strong> (syndrome médullaire aigu).</li><li>Un <strong><span class=\"nc-red_bg\">hémopéricarde avec tamponnade</span></strong>.</li><li>Un <strong><span class=\"nc-red_bg\">infarctus mésentérique</span></strong>.</li><li>Une <strong><span class=\"nc-red_bg\">ischémie aiguë d'un membre</span></strong>.</li><li>Une <strong><span class=\"nc-red_bg\">insuffisance rénale aiguë</span></strong>.</li></ul></div>"},{"i":"5a80a1907088","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","q":"Quels sont les facteurs de risque et les terrains favorisants d'une dissection aortique ?","a":"<div class=\"notion-course\"><p>Les facteurs de risque et terrains favorisants d'une dissection aortique sont :</p><ul><li>Une <strong><span class=\"nc-orange_bg\">HTA ancienne</span></strong> et l'<strong><span class=\"nc-orange_bg\">athérome</span></strong>, retrouvés principalement chez le sujet âgé (en général <span class=\"nc-pink nc-bold\">&gt; 60 ans</span>).</li><li>Des syndromes génétiques tels que le <strong><span class=\"nc-orange_bg\">syndrome de Marfan</span></strong> ou d'<strong>Ehlers-Danlos</strong>, rencontrés chez le sujet plus jeune.</li><li>Un <strong>antécédent familial de maladie aortique</strong>.</li><li>Un <strong><span class=\"nc-orange_bg\">anévrisme de l'aorte thoracique</span></strong> ou une <strong>valvulopathie aortique connue</strong>.</li><li>Un <strong>antécédent de chirurgie aortique</strong>.</li></ul></div>"},{"i":"8b8ea39e5c55","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","q":"Quelle est la valeur diagnostique d'un score clinique de probabilité pour la dissection aortique ?","a":"<div class=\"notion-course\"><ul><li>ADD-RS : 1 point par catégorie (terrain, douleur, examen), total 0–3.</li><li>0 faible ; 1 intermédiaire ; 2–3 élevé. Certains parcours regroupent 0–1 pour une exclusion combinée avec D-dimères ; le score seul ne suffit pas.</li></ul></div>"},{"i":"9e15da0f1a7a","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","q":"Quels sont les signes fonctionnels évocateurs d'une dissection aortique ?","a":"<div class=\"notion-course\"><p>Le signe fonctionnel principal d'une dissection aortique est la douleur, caractérisée par :</p><ul><li>Un début <strong>aigu et brutal</strong>.</li><li>Une nature <strong>intense</strong>, à type de <strong><span class=\"nc-red nc-bold\">déchirement</span></strong> ou en <strong><span class=\"nc-red nc-bold\">coup de poignard</span></strong> (transfixiante).</li><li>Une <strong>irradiation dans le <span class=\"nc-blue_bg\">dos</span></strong>, souvent <strong>migratrice</strong>, descendant vers les <span class=\"nc-blue_bg\">lombes</span> et les <span class=\"nc-blue_bg\">membres inférieurs</span>.</li><li>Parfois accompagnée d'une <strong>syncope</strong>.</li></ul></div>"},{"i":"c81fc7fb0972","n":230,"o":"230-5","u":"Diagnostic positif","t":"Connaître la sémiologie clinique fonctionnelle et physique de la dissection aortique","q":"Quelle est la contre-indication majeure à connaître en cas de suspicion de dissection aortique, et pourquoi ?","a":"<div class=\"notion-course\"><p>Ne pas administrer empiriquement anticoagulants curatifs ou fibrinolyse devant une suspicion de dissection : risque hémorragique et retard de chirurgie. Toute indication antithrombotique concomitante est discutée avec l’équipe aortique.</p></div>"},{"i":"16fe69436990","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelles sont les classifications de la dissection aortique de Stanford et DeBakey ?","a":"<div class=\"notion-course\"><p>Les classifications de la dissection aortique sont :</p><ul><li><strong>Stanford :</strong><ul><li><strong>Type A :</strong> Atteinte de l'<span class=\"nc-yellow_bg\">aorte ascendante</span>.</li><li><strong>Type B :</strong> <span class=\"nc-yellow_bg\">Aorte ascendante</span> respectée (dissection limitée à l'aorte descendante).</li></ul></li><li><strong>DeBakey :</strong><ul><li><strong>Type I :</strong> Porte d'entrée sur l'<span class=\"nc-yellow_bg\">aorte ascendante</span> avec extension à l'aorte descendante.</li><li><strong>Type II :</strong> Limitée à l'<span class=\"nc-yellow_bg\">aorte ascendante</span>.</li><li><strong>Type III :</strong> Porte d'entrée <span class=\"nc-red nc-bold\">après l'artère sous-clavière gauche</span>.</li></ul></li></ul></div>"},{"i":"6eccc68b7e10","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelle est la première étape systématique de la démarche diagnostique face à une douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>La première étape est la recherche systématique et rapide d'une <strong>détresse vitale</strong> : respiratoire, hémodynamique ou neurologique.</p></div>"},{"i":"78372a68acfd","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quels examens initiaux orientent une douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><ul><li>Constantes et SpO₂ ; ECG 12 dérivations rapidement, en moins de 10 min si suspicion de SCA, complété selon contexte.</li><li>Troponine si SCA suspecté. Radiographie, échographie et autres examens selon hypothèse ; pas de bilan identique pour tous.</li></ul></div>"},{"i":"a19563e9745e","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Que montrent l’ETO et l’angio-TDM dans la dissection aortique ?","a":"<div class=\"notion-course\"><ul><li>Le flap intimal sépare vrai et <span class=\"nc-brown_bg\">faux chenal</span>.</li><li><span class=\"nc-blue_bg\">Angio-TDM</span> : examen majeur chez le patient stable, cartographie aorte, porte d’entrée, branches et complications.</li><li>Instabilité : échographie au lit/ETO selon disponibilité, avis urgent ; transport au scanner uniquement s’il est compatible avec les soins.</li></ul></div>"},{"i":"cebef01e68d8","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelles sont les quatre urgences cardiovasculaires à évoquer systématiquement devant une douleur thoracique, selon l'acronyme PIED ?","a":"<div class=\"notion-course\"><p>Les quatre urgences cardiovasculaires à évoquer sont :</p><ul><li><strong>P</strong>éricardite</li><li><strong>I</strong>nfarctus du myocarde (syndrome coronarien aigu)</li><li><strong>E</strong>mbolie pulmonaire</li><li><strong>D</strong>issection aortique</li></ul></div>"},{"i":"ec97c5461f4a","n":230,"o":"230-6","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des quatre urgences cardio-vasculaires","q":"Quelle est la démarche diagnostique par imagerie et biologie en cas de suspicion de dissection aortique chez un patient stable avec une faible probabilité clinique ?","a":"<div class=\"notion-course\"><p>Chez le patient stable à faible probabilité, utiliser une stratégie validée combinant clinique et <span class=\"nc-blue_bg\">D-dimères</span>. Une radiographie normale ou des <span class=\"nc-blue_bg\">D-dimères</span> négatifs isolés ne suffisent pas ; si suspicion persistante/élevée, <span class=\"nc-blue_bg\">angio-TDM</span> sans délai.</p></div>"},{"i":"20ce0974d045","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quelles anomalies électrocardiographiques caractérisent un syndrome coronarien aigu (SCA) ?","a":"<div class=\"notion-course\"><p>Les anomalies ECG évocatrices d'un SCA sont :</p><ul><li>Un <strong>sus-décalage ST</strong>.</li><li>Un <strong>sous-décalage ST</strong>.</li><li>Des anomalies de l'<strong>onde T</strong> (négative, pointue, etc.).</li></ul></div>"},{"i":"27684a310466","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quel est l'apport de l'électrocardiogramme (ECG) dans le diagnostic d'une dissection aortique et quels sont ses pièges ?","a":"<div class=\"notion-course\"><p>L'ECG est généralement <strong>peu contributif</strong> dans le diagnostic de dissection aortique et est le plus souvent <strong>normal</strong>. Cependant, en cas d'extension de la dissection à une artère coronaire, l'ECG peut mimer un <strong>syndrome coronarien aigu (<span class=\"nc-red nc-bold\">SCA</span>)</strong>, présentant un sous-décalage ST, un sus-décalage ST ou une inversion de l'onde T. Le piège est qu'un ECG d'allure de <span class=\"nc-red nc-bold\">SCA</span> n'élimine pas une dissection aortique, exposant au risque d'<strong>anticoaguler à tort</strong> une dissection.</p></div>"},{"i":"9574c6037dfb","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quelles sont les anomalies électrocardiographiques typiques de la péricardite aiguë ?","a":"<div class=\"notion-course\"><p>L'ECG d'une péricardite aiguë est caractérisé par :</p><ul><li>Un <strong>sus-décalage ST concave vers le haut</strong>, généralement <strong>diffus</strong>.</li><li>Un <strong>sous-décalage du segment PQ</strong>.</li></ul></div>"},{"i":"d976cd17ded3","n":230,"o":"230-7","u":"Examens complémentaires","t":"Connaître les anomalies électrocardiographiques des quatre urgences cardio-vasculaires","q":"Quelles anomalies électrocardiographiques observe-t-on en cas d'embolie pulmonaire ?","a":"<div class=\"notion-course\"><p>En cas d'embolie pulmonaire, l'ECG peut montrer :</p><ul><li>Une <strong>tachycardie sinusale</strong>.</li><li>Un <strong>bloc de branche droit</strong>.</li><li>Des <strong>ondes T négatives</strong>.</li><li>Un aspect <strong>S1Q3</strong> (onde S en D1, onde Q en D3, et onde T négative en D3 est parfois précisé).</li></ul></div>"},{"i":"0c3a698d9d3d","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quelle est la valeur de la radiographie thoracique en cas de suspicion d'embolie pulmonaire ou de péricardite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Pour l'<strong>embolie pulmonaire</strong>, la radiographie <span class=\"nc-blue_bg\">thoracique</span> est <strong>souvent normale</strong>. Les signes sont inconstants et peu spécifiques, et ne permettent pas de confirmer ni d'exclure le diagnostic.</li><li>Pour la <strong>péricardite</strong>, la radiographie est <strong>normale en règle générale</strong>. Une <strong>cardiomégalie</strong> peut être visible uniquement en cas d'épanchement péricardique abondant.</li></ul></div>"},{"i":"181eb250b540","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quelle est la place générale de la radiographie thoracique dans l'évaluation d'une douleur thoracique aiguë, en particulier vis-à-vis des urgences cardiovasculaires ?","a":"<div class=\"notion-course\"><p>Radiographie ciblée pour pneumothorax, pneumonie, épanchement ou congestion. Elle peut orienter mais n’exclut ni EP ni dissection ; ne pas retarder une reperfusion.</p></div>"},{"i":"49b8e6deac07","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quels signes radiologiques thoraciques peuvent orienter vers une dissection aortique ?","a":"<div class=\"notion-course\"><p>Devant une suspicion de dissection aortique, la radiographie <span class=\"nc-blue_bg\">thoracique</span> peut montrer :</p><ul><li>Un <strong><span class=\"nc-blue_bg\">élargissement du médiastin</span> supérieur</strong> (signe le plus fréquent).</li><li>Un éventuel <strong>épanchement pleural</strong> (hémothorax en cas de <span class=\"nc-red nc-bold\">rupture</span> aortique).</li><li>Un <strong>double contour aortique</strong> peut parfois être visible.</li></ul></div>"},{"i":"6d4e50d5f518","n":230,"o":"230-8","u":"Examens complémentaires","t":"Connaître la place et les anomalies de la radiographie thoracique des quatre urgences cardio-vasculaires","q":"Quelles sont les anomalies à rechercher à la radiographie thoracique en cas de syndrome coronaire aigu (SCA) avec douleur thoracique ?","a":"<div class=\"notion-course\"><p>En cas de SCA, la radiographie <span class=\"nc-blue_bg\">thoracique</span> est <strong>normale en règle générale</strong>, car il n'y a pas de signe radiologique spécifique de l'infarctus. Cependant, elle peut rechercher des signes d'<strong>insuffisance cardiaque</strong> (ex: œdème pulmonaire).</p></div>"},{"i":"1b7faa7e41b0","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Quels bilans biologiques complémentaires sont requis en cas de suspicion de dissection aortique, en dehors des troponines et D-dimères ?","a":"<div class=\"notion-course\"><ul><li>NFS-<span class=\"nc-blue_bg\">plaquettes</span>, créatinine, ionogramme, hémostase et groupage selon gravité/geste.</li><li>Lactate si hypoperfusion ; CK si ischémie musculaire/rhabdomyolyse suspectée. Ne pas retarder l’imagerie ou la chirurgie.</li></ul></div>"},{"i":"32ba648a7dfd","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Dans quelles situations de douleur thoracique aiguë les D-dimères ont-ils une utilité diagnostique et quelle est leur principale valeur ?","a":"<div class=\"notion-course\"><ul><li>EP : exclusion possible si résultat négatif selon seuil validé et probabilité non élevée.</li><li>Dissection : usage uniquement dans une stratégie validée à faible probabilité ; ils ne sont pas toujours élevés et ne remplacent pas l’imagerie si forte suspicion.</li></ul></div>"},{"i":"81dfd728d250","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Dans quel contexte de douleur thoracique aiguë les troponines ultrasensibles sont-elles surtout contributives, et peuvent-elles être élevées dans une péricardite ?","a":"<div class=\"notion-course\"><ul><li>Surtout utile dans le SCA sans sus-ST : la cinétique et les signes d’ischémie permettent d’interpréter une lésion myocardique.</li><li>Une troponine élevée peut accompagner une myocardite/<span class=\"nc-red_bg\">myopéricardite</span> ; elle ne prouve pas un SCA.</li></ul></div>"},{"i":"e20dfa671cdf","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Quels sont les deux examens biologiques fondamentaux à la démarche diagnostique devant une douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>Troponine ultrasensible si suspicion de SCA ; <span class=\"nc-blue_bg\">D-dimères</span> uniquement dans une stratégie clinique adaptée pour EP ou syndrome aortique aigu. Ils ne sont pas systématiques dans toute douleur <span class=\"nc-blue_bg\">thoracique</span>.</p></div>"},{"i":"e5e6e9c232a6","n":230,"o":"230-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à prescrire et leur interprétation des quatre urgences cardio-vasculaires","q":"Quelle est l'interprétation d'une élévation des troponines ultrasensibles en contexte de douleur thoracique aiguë ?","a":"<div class=\"notion-course\"><p>Une élévation indique une lésion myocardique, possible dans SCA, EP, dissection, myocardite, IC ou insuffisance rénale. Cinétique, ECG et signes d’ischémie précisent la cause.</p></div>"},{"i":"72aba6ab456d","n":230,"o":"230-10","u":"Examens complémentaires","t":"Connaître la place de la coronarographie dans le diagnostic et les principes de prise en charge du syndrome coronarien aigu","q":"Quels sont les deux délais à distinguer avant une fibrinolyse de SCA ST+ ?","a":"<div class=\"notion-course\"><ul><li>Symptômes depuis moins de 12 h ; délai estimé diagnostic → passage du guide supérieur à 120 min.</li><li>Vérifier les contre-indications, puis transférer immédiatement vers un centre d’angioplastie.</li></ul></div>"},{"i":"09c31ffee809","n":230,"o":"230-11","u":"Examens complémentaires","t":"Connaître la place de l’échocardiographie","q":"Une échocardiographie normale exclut-elle les urgences responsables d’une douleur thoracique ?","a":"<div class=\"notion-course\"><ul><li>Non : elle n’exclut ni SCA, ni EP, ni dissection ; compléter selon la probabilité clinique.</li></ul></div>"},{"i":"506a6cd80097","n":230,"o":"230-12","u":"Étiologies","t":"Devant un angor d’effort, connaître les principales causes d’angor fonctionnel","q":"Quelles causes peuvent produire un angor par déséquilibre apports/besoins ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-brown_bg\">Anémie</span>, tachycardie, <span class=\"nc-brown_bg\">hyperthyroïdie</span>, <span class=\"nc-brown_bg\">rétrécissement aortique serré</span>, <span class=\"nc-brown_bg\">cardiomyopathie hypertrophique</span> ou HTAP sévère.</li><li>Ces facteurs peuvent coexister avec une coronaropathie ; absence de sténose ne signifie pas absence de maladie coronaire fonctionnelle.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181209d63f2a2159ac829?pvs=204","reviewedAt":"2026-10-15","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif."}};
